import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { PrismaService } from '../prisma/prisma.service';
import { auditContextStorage } from './audit.context';

@Injectable()
export class AuditHandler {
  constructor(private readonly prisma: PrismaService) {}

  @OnEvent('domain.event.*')
  async handleAuditLogEvent(event: {
    entityType: string;
    entityId: string;
    action: string; // Must be 'CREATE' | 'UPDATE' | 'DELETE' based on Prisma Schema
    previousData?: unknown;
    newData?: unknown;
  }) {
    const context = auditContextStorage.getStore();

    // Use user_id from context, or fallback to a known SYSTEM UUID
    const userId = context?.userId || '00000000-0000-0000-0000-000000000000';

    await this.prisma.auditLog.create({
      data: {
        user_id: userId,
        entity_type: event.entityType,
        entity_id: event.entityId,
        action: event.action,
        previous_data: event.previousData ? (event.previousData as any) : undefined,
        new_data: event.newData ? (event.newData as any) : undefined,
        request_id: context?.requestId,
        correlation_id: context?.correlationId,
      },
    });
  }
}

import { Injectable } from '@nestjs/common';
import { Account as PrismaAccount } from '@mymoney/db';
import { IAccountRepository } from '../../domain/interfaces/account.repository.interface';
import { Account } from '../../domain/account.entity';
import { Currency, Money } from '@mymoney/shared';
import { AccountType } from '../../domain/account-type.enum';
import { PrismaService } from '../../../../prisma/prisma.service';

@Injectable()
export class PrismaAccountRepository implements IAccountRepository {
  constructor(private readonly prisma: PrismaService) {}

  private toDomain(raw: PrismaAccount): Account {
    return Account.reconstitute({
      id: raw.id,
      userId: raw.user_id,
      name: raw.name,
      type: raw.type as AccountType,
      currency: raw.currency as Currency,
      initialBalance: Money.of(raw.initial_balance.toString(), raw.currency as Currency),
      currentBalance: Money.of(raw.current_balance.toString(), raw.currency as Currency),
      color: raw.color,
      icon: raw.icon,
      isActive: raw.is_active,
      createdAt: raw.created_at,
      createdBy: raw.created_by,
      updatedAt: raw.updated_at,
      updatedBy: raw.updated_by,
      deletedAt: raw.deleted_at,
      deletedBy: raw.deleted_by,
    });
  }

  async findById(id: string, userId: string): Promise<Account | null> {
    const raw = await this.prisma.account.findFirst({
      where: { 
        id, 
        user_id: userId,
        deleted_at: null 
      },
    });
    return raw ? this.toDomain(raw) : null;
  }

  async exists(id: string, userId: string): Promise<boolean> {
    const count = await this.prisma.account.count({
      where: { id, user_id: userId, deleted_at: null }
    });
    return count > 0;
  }

  async softDelete(id: string, userId: string, deletedBy: string): Promise<void> {
    await this.prisma.account.updateMany({
      where: { id, user_id: userId },
      data: {
        deleted_at: new Date(),
        deleted_by: deletedBy,
        updated_at: new Date(),
        updated_by: deletedBy,
        is_active: false
      }
    });
  }

  async findAllActiveByUser(userId: string): Promise<Account[]> {
    const rawList = await this.prisma.account.findMany({
      where: { 
        user_id: userId,
        deleted_at: null 
      },
      orderBy: { name: 'asc' },
    });
    return rawList.map(raw => this.toDomain(raw));
  }

  async save(account: Account): Promise<void> {
    const data = {
      user_id: account.userId,
      name: account.name,
      type: account.type,
      currency: account.currency,
      initial_balance: account.initialBalance.value.toFixed(4),
      current_balance: account.currentBalance.value.toFixed(4),
      color: account.color,
      icon: account.icon,
      is_active: account.isActive(),
      created_by: account.createdBy,
      updated_at: (account as any)._updatedAt,
      updated_by: (account as any)._updatedBy,
      deleted_at: (account as any)._deletedAt,
      deleted_by: (account as any)._deletedBy,
    };

    await this.prisma.account.upsert({
      where: { id: account.id },
      create: {
        id: account.id,
        created_at: account.createdAt,
        ...data,
      },
      update: data,
    });
  }

  async hasTransactions(accountId: string): Promise<boolean> {
    const count = await this.prisma.transaction.count({
      where: { account_id: accountId },
    });
    return count > 0;
  }

  async existsByNameAndUser(name: string, userId: string): Promise<boolean> {
    const count = await this.prisma.account.count({
      where: { 
        name, 
        user_id: userId,
        deleted_at: null
      },
    });
    return count > 0;
  }
}

import { 
  Controller, 
  Get, 
  Post, 
  Patch, 
  Delete, 
  Body, 
  Param, 
  UseGuards, 
  Request,
  HttpCode,
  HttpStatus
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse,  ApiCookieAuth } from '@nestjs/swagger';
import { SessionGuard } from '../../../auth/session.guard';
import { 
  CreateAccountUseCase,
  UpdateAccountUseCase,
  DeleteAccountUseCase,
  GetAccountUseCase,
  ListAccountsUseCase
} from '../application/use-cases';
import { CreateAccountDto, UpdateAccountDto, AccountDto } from '../presentation/dtos';

@ApiTags('Accounts')
@ApiCookieAuth('session_id')
@UseGuards(SessionGuard)
@Controller({ path: 'accounts', version: '1' })
export class AccountsController {
  constructor(
    private readonly createAccountUseCase: CreateAccountUseCase,
    private readonly updateAccountUseCase: UpdateAccountUseCase,
    private readonly deleteAccountUseCase: DeleteAccountUseCase,
    private readonly getAccountUseCase: GetAccountUseCase,
    private readonly listAccountsUseCase: ListAccountsUseCase
  ) {}

  @Get()
  @ApiOperation({ summary: 'List all active accounts for the authenticated user' })
  @ApiResponse({ status: 200, description: 'Return all accounts.', type: [AccountDto] })
  async findAll(@Request() req: any) {
    const userId = req.user.id;
    return this.listAccountsUseCase.execute(userId);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get account details' })
  @ApiResponse({ status: 200, description: 'Return account details.', type: AccountDto })
  async findOne(@Param('id') id: string, @Request() req: any) {
    const userId = req.user.id;
    return this.getAccountUseCase.execute(id, userId);
  }

  @Post()
  @ApiOperation({ summary: 'Create a new account' })
  @ApiResponse({ status: 201, description: 'The account has been successfully created.', type: AccountDto })
  async create(@Body() createAccountDto: CreateAccountDto, @Request() req: any) {
    const userId = req.user.id;
    return this.createAccountUseCase.execute(userId, createAccountDto);
  }

  @Patch(':id')
  @ApiOperation({ summary: 'Update an account' })
  @ApiResponse({ status: 200, description: 'The account has been successfully updated.', type: AccountDto })
  async update(
    @Param('id') id: string, 
    @Body() updateAccountDto: UpdateAccountDto, 
    @Request() req: any
  ) {
    const userId = req.user.id;
    return this.updateAccountUseCase.execute(id, userId, updateAccountDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({ summary: 'Archive an account' })
  @ApiResponse({ status: 204, description: 'The account has been successfully archived.' })
  async remove(@Param('id') id: string, @Request() req: any) {
    const userId = req.user.id;
    await this.deleteAccountUseCase.execute(id, userId);
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { CategoryDeletedEvent } from '../../../categories/domain/category.events';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class DeactivateBudgetsOnCategoryDeletedHandler {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  @OnEvent('CategoryDeleted')
  async handle(event: CategoryDeletedEvent) {
    // Find all budgets for this category
    const budgets = await this.budgetRepository.findByCategory(event.categoryId, event.userId);

    const activeBudgets = budgets.filter(b => b.isActive());

    if (activeBudgets.length === 0) return;

    await this.unitOfWork.execute(async () => {
      for (const budget of activeBudgets) {
        budget.deactivate('CATEGORY_DELETED');
        await this.budgetRepository.save(budget);
      }
    });

    // Emits if there are any events (though deactivate currently doesn't emit domain events, just in case)
    for (const budget of activeBudgets) {
      budget.getDomainEvents().forEach((evt: any) => this.eventEmitter.emit(evt.type, evt));
      budget.clearDomainEvents();
    }
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { TransactionAmountChangedEvent, IUnitOfWork, UNIT_OF_WORK, BalanceDelta, Money, Currency } from '@mymoney/shared';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class UpdateBudgetOnTransactionAmountChangedHandler {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  @OnEvent('TransactionAmountChanged')
  async handle(event: TransactionAmountChangedEvent) {
    if (event.transactionType !== 'EXPENSE') return;
    if (!event.categoryId) return;

    const date = new Date(event.date);
    const previousAmount = Money.of(event.previousAmount.value, event.previousAmount.currency as Currency);
    const newAmount = Money.of(event.newAmount.value, event.newAmount.currency as Currency);

    const budget = await this.budgetRepository.findActiveByCategoryAndDate(
      event.categoryId,
      event.userId,
      date
    );

    if (!budget) return;

    // Delta between new and old
    const difference = newAmount.subtract(previousAmount);

    if (difference.value.gt(0)) {
      budget.applyTransactionDelta(BalanceDelta.increase(difference), date);
    } else if (difference.value.lt(0)) {
      // difference is negative, so invert it for decrease
      budget.applyTransactionDelta(BalanceDelta.decrease(Money.of(difference.value.abs(), difference.currency)), date);
    }

    await this.unitOfWork.execute(async () => {
      await this.budgetRepository.save(budget);
    });

    // Emit budget events
    budget.getDomainEvents().forEach((evt: any) => this.eventEmitter.emit(evt.type, evt));
    budget.clearDomainEvents();
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { TransactionCategoryChangedEvent, IUnitOfWork, UNIT_OF_WORK, BalanceDelta, Money, Currency } from '@mymoney/shared';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class UpdateBudgetOnTransactionCategoryChangedHandler {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  @OnEvent('TransactionCategoryChanged')
  async handle(event: TransactionCategoryChangedEvent) {
    if (event.transactionType !== 'EXPENSE') return;

    const date = new Date(event.date);
    const amount = Money.of(event.amount.value, event.amount.currency as Currency);

    const budgetPreviousCat = event.previousCategoryId 
      ? await this.budgetRepository.findActiveByCategoryAndDate(event.previousCategoryId, event.userId, date)
      : null;

    const budgetNewCat = event.newCategoryId 
      ? await this.budgetRepository.findActiveByCategoryAndDate(event.newCategoryId, event.userId, date)
      : null;

    await this.unitOfWork.execute(async () => {
      if (budgetPreviousCat) {
        budgetPreviousCat.applyTransactionDelta(BalanceDelta.decrease(amount), date);
        await this.budgetRepository.save(budgetPreviousCat);
      }

      if (budgetNewCat) {
        budgetNewCat.applyTransactionDelta(BalanceDelta.increase(amount), date);
        await this.budgetRepository.save(budgetNewCat);
      }
    });

    // Emit budget events outside transaction
    if (budgetPreviousCat) {
      budgetPreviousCat.getDomainEvents().forEach((evt: any) => this.eventEmitter.emit(evt.type, evt));
      budgetPreviousCat.clearDomainEvents();
    }

    if (budgetNewCat) {
      budgetNewCat.getDomainEvents().forEach((evt: any) => this.eventEmitter.emit(evt.type, evt));
      budgetNewCat.clearDomainEvents();
    }
  }
}

