import { Injectable, Inject, NotFoundException, UnprocessableEntityException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Money, Currency, IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { Budget } from '../../domain/budget.entity';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { CreateBudgetDto } from '../../presentation/dtos/create-budget.dto';
import { BudgetDto } from '../../presentation/dtos/budget.dto';
import { BudgetAlreadyExistsException } from '../../domain/exceptions/budget.exceptions';
import { ICategoryRepository, CATEGORY_REPOSITORY } from '../../../categories/domain/category.repository.interface';

@Injectable()
export class CreateBudgetUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(CATEGORY_REPOSITORY)
    private readonly categoryRepository: ICategoryRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, dto: CreateBudgetDto): Promise<BudgetDto> {
    const category = await this.categoryRepository.findById(dto.category_id, userId);
    if (!category) {
      throw new NotFoundException('Category not found');
    }

    if (category.type !== 'EXPENSE' && category.type !== 'BOTH') {
      throw new UnprocessableEntityException('Cannot create budget for INCOME category');
    }

    const startDate = new Date(dto.start_date);

    // Validates BGT-R01
    const exists = await this.budgetRepository.existsActiveBudget(
      userId,
      dto.category_id,
      dto.period,
      startDate
    );

    if (exists) {
      throw new BudgetAlreadyExistsException();
    }

    const amount = Money.of(dto.amount, dto.currency as Currency);

    const budget = Budget.create({
      userId,
      categoryId: dto.category_id,
      period: dto.period,
      amount,
      startDate,
      alertThreshold: dto.alert_threshold,
    });

    await this.unitOfWork.execute(async () => {
      await this.budgetRepository.save(budget);
    });

    // Emit events
    budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    budget.clearDomainEvents();

    return BudgetDto.fromDomain(budget);
  }
}

import { Injectable, Inject, NotFoundException, UnprocessableEntityException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { BudgetNotActiveException } from '../../domain/exceptions/budget.exceptions';

@Injectable()
export class DeactivateBudgetUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, budgetId: string): Promise<void> {
    const budget = await this.budgetRepository.findById(budgetId, userId);
    if (!budget) {
      throw new NotFoundException('Budget not found');
    }

    try {
      budget.deactivate('USER_REQUEST');
    } catch (error) {
      if (error instanceof BudgetNotActiveException) {
        throw new UnprocessableEntityException('El presupuesto ya no está activo.');
      }
      throw error;
    }

    await this.unitOfWork.execute(async () => {
      await this.budgetRepository.save(budget);
    });

    // Emit events
    budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    budget.clearDomainEvents();
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { EventEmitter2 } from '@nestjs/event-emitter';
import {  BudgetStatus } from '../../domain/budget.entity';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { BudgetDto } from '../../presentation/dtos/budget.dto';

@Injectable()
export class GetBudgetByIdUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, budgetId: string): Promise<BudgetDto> {
    const budget = await this.budgetRepository.findById(budgetId, userId);
    if (!budget) {
      throw new NotFoundException('Budget not found');
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (budget.status === BudgetStatus.ACTIVE && budget.endDate.getTime() < today.getTime()) {
      await this.unitOfWork.execute(async () => {
        budget.expire();
        await this.budgetRepository.save(budget);
      });

      budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
      budget.clearDomainEvents();
    }

    return BudgetDto.fromDomain(budget);
  }
}

import { Injectable, Inject} from '@nestjs/common';
import { IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { Budget, BudgetStatus } from '../../domain/budget.entity';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { BudgetDto } from '../../presentation/dtos/budget.dto';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class GetBudgetsUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async findAll(userId: string, status?: string, categoryId?: string): Promise<BudgetDto[]> {
    let budgets = await this.budgetRepository.findAllByUser(userId);

    // Lazy check for expiration
    budgets = await this.processLazyExpiration(budgets);

    if (status) {
      budgets = budgets.filter(b => b.status === status as BudgetStatus);
    }
    if (categoryId) {
      budgets = budgets.filter(b => b.categoryId === categoryId);
    }

    return budgets.map(b => BudgetDto.fromDomain(b));
  }



  private async processLazyExpiration(budgets: Budget[]): Promise<Budget[]> {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const expiredBudgets = budgets.filter(b => 
      b.status === BudgetStatus.ACTIVE && b.endDate.getTime() < today.getTime()
    );

    if (expiredBudgets.length > 0) {
      await this.unitOfWork.execute(async () => {
        for (const budget of expiredBudgets) {
          budget.expire();
          await this.budgetRepository.save(budget);
        }
      });

      // Emit events outside transaction
      for (const budget of expiredBudgets) {
        budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
        budget.clearDomainEvents();
      }
    }

    return budgets;
  }
}

import { Injectable, Inject, NotFoundException, UnprocessableEntityException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { BudgetDto } from '../../presentation/dtos/budget.dto';

@Injectable()
export class ReactivateBudgetUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, budgetId: string): Promise<BudgetDto> {
    const budget = await this.budgetRepository.findById(budgetId, userId);
    if (!budget) {
      throw new NotFoundException('Budget not found');
    }

    try {
      budget.reactivate();
    } catch (error) {
      if (error instanceof Error && error.message === 'Only inactive budgets can be reactivated') {
        throw new UnprocessableEntityException(error.message);
      }
      throw error;
    }

    await this.unitOfWork.execute(async () => {
      await this.budgetRepository.save(budget);
    });

    // Emit events
    budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    budget.clearDomainEvents();

    return BudgetDto.fromDomain(budget);
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Money, IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { IBudgetRepository, BUDGET_REPOSITORY } from '../../domain/budget.repository.interface';
import { UpdateBudgetDto } from '../../presentation/dtos/update-budget.dto';
import { BudgetDto } from '../../presentation/dtos/budget.dto';

@Injectable()
export class UpdateBudgetUseCase {
  constructor(
    @Inject(BUDGET_REPOSITORY)
    private readonly budgetRepository: IBudgetRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, budgetId: string, dto: UpdateBudgetDto): Promise<BudgetDto> {
    const budget = await this.budgetRepository.findById(budgetId, userId);
    if (!budget) {
      throw new NotFoundException('Budget not found');
    }

    if (dto.amount) {
      budget.updateAmount(Money.of(dto.amount, budget.amount.currency));
    }

    if (dto.alert_threshold) {
      budget.updateAlertThreshold(dto.alert_threshold);
    }

    await this.unitOfWork.execute(async () => {
      await this.budgetRepository.save(budget);
    });

    // Emit events
    budget.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    budget.clearDomainEvents();

    return BudgetDto.fromDomain(budget);
  }
}

import { randomUUID } from 'crypto';
import { Money, BalanceDelta } from '@mymoney/shared';
import { 
  InvalidBudgetAmountException, 
  InvalidAlertThresholdException, 
  BudgetNotActiveException
} from './exceptions/budget.exceptions';
import { BudgetThresholdReachedEvent } from './events/budget-threshold-reached.event';
import { BudgetExceededEvent } from './events/budget-exceeded.event';
import { BudgetExpiredEvent } from './events/budget-expired.event';

export enum BudgetPeriod {
  WEEKLY = 'WEEKLY',
  MONTHLY = 'MONTHLY',
  YEARLY = 'YEARLY',
}

export enum BudgetStatus {
  ACTIVE = 'ACTIVE',
  EXPIRED = 'EXPIRED',
  INACTIVE = 'INACTIVE',
}

export interface CreateBudgetProps {
  userId: string;
  categoryId: string;
  period: BudgetPeriod;
  amount: Money;
  startDate: Date;
  alertThreshold?: number;
}

export interface BudgetProps {
  id: string;
  userId: string;
  categoryId: string;
  period: BudgetPeriod;
  amount: Money;
  startDate: Date;
  endDate: Date;
  alertThreshold: number;
  executedAmount: Money;
  status: BudgetStatus;
  createdAt: Date;
  updatedAt: Date;
}

export class Budget {
  private props: BudgetProps;
  private domainEvents: unknown[] = [];

  private constructor(props: BudgetProps) {
    this.props = props;
  }

  // Getters
  get id(): string { return this.props.id; }
  get userId(): string { return this.props.userId; }
  get categoryId(): string { return this.props.categoryId; }
  get period(): BudgetPeriod { return this.props.period; }
  get startDate(): Date { return this.props.startDate; }
  get endDate(): Date { return this.props.endDate; }
  get amount(): Money { return this.props.amount; }
  get alertThreshold(): number { return this.props.alertThreshold; }
  get executedAmount(): Money { return this.props.executedAmount; }
  get status(): BudgetStatus { return this.props.status; }
  get createdAt(): Date { return this.props.createdAt; }
  get updatedAt(): Date { return this.props.updatedAt; }

  // Events
  public getDomainEvents(): unknown[] {
    return [...this.domainEvents];
  }

  public clearDomainEvents(): void {
    this.domainEvents = [];
  }

  private addDomainEvent(event: any): void {
    this.domainEvents.push(event);
  }

  static create(props: CreateBudgetProps): Budget {
    if (props.amount.value.lte(0)) {
      throw new InvalidBudgetAmountException();
    }
    const alertThreshold = props.alertThreshold ?? 80;
    if (alertThreshold < 1 || alertThreshold > 100) {
      throw new InvalidAlertThresholdException();
    }

    const startDate = new Date(props.startDate);
    let endDate: Date;
    switch (props.period) {
      case BudgetPeriod.WEEKLY:
        endDate = new Date(startDate);
        endDate.setUTCDate(startDate.getUTCDate() + 6);
        break;
      case BudgetPeriod.MONTHLY:
        endDate = new Date(Date.UTC(startDate.getUTCFullYear(), startDate.getUTCMonth() + 1, 0)); // last day of month
        break;
      case BudgetPeriod.YEARLY:
        endDate = new Date(Date.UTC(startDate.getUTCFullYear(), 11, 31)); // Dec 31st of the start year
        break;
    }

    return new Budget({
      id: randomUUID(),
      userId: props.userId,
      categoryId: props.categoryId,
      period: props.period,
      amount: props.amount,
      startDate,
      endDate,
      alertThreshold,
      executedAmount: Money.zero(props.amount.currency),
      status: BudgetStatus.ACTIVE,
      createdAt: new Date(),
      updatedAt: new Date(),
    });
  }

  static reconstitute(props: BudgetProps): Budget {
    return new Budget(props);
  }

  public updateAmount(newAmount: Money): void {
    if (newAmount.value.lte(0)) {
      throw new InvalidBudgetAmountException();
    }
    if (this.props.status !== BudgetStatus.ACTIVE) {
      throw new BudgetNotActiveException();
    }
    this.props.amount = newAmount;
    this.props.updatedAt = new Date();
  }

  public updateAlertThreshold(threshold: number): void {
    if (threshold < 1 || threshold > 100) {
      throw new InvalidAlertThresholdException();
    }
    if (this.props.status !== BudgetStatus.ACTIVE) {
      throw new BudgetNotActiveException();
    }
    this.props.alertThreshold = threshold;
    this.props.updatedAt = new Date();
  }

  public applyTransactionDelta(delta: BalanceDelta, transactionDate: Date): void {
    if (!this.isActive() || !this.containsDate(transactionDate)) {
      return;
    }

    const previousPercentage = this.executionPercentage();

    if (delta.direction === 'INCREASE') {
      this.props.executedAmount = this.props.executedAmount.add(delta.amount);
    } else {
      this.props.executedAmount = this.props.executedAmount.subtract(delta.amount);
      if (this.props.executedAmount.value.lt(0)) {
        this.props.executedAmount = Money.zero(this.props.amount.currency);
      }
    }

    this.props.updatedAt = new Date();

    const newPercentage = this.executionPercentage();

    // Check thresholds
    if (previousPercentage < this.props.alertThreshold && newPercentage >= this.props.alertThreshold) {
      this.addDomainEvent(new BudgetThresholdReachedEvent({
        aggregateId: this.id,
        userId: this.userId,
        categoryId: this.categoryId,
        threshold: this.props.alertThreshold,
        executedAmount: { value: this.props.executedAmount.value.toString(), currency: this.props.executedAmount.currency },
        budgetAmount: { value: this.props.amount.value.toString(), currency: this.props.amount.currency },
      }));
    }

    if (previousPercentage < 100 && newPercentage >= 100) {
      this.addDomainEvent(new BudgetExceededEvent({
        aggregateId: this.id,
        userId: this.userId,
        categoryId: this.categoryId,
        executedAmount: { value: this.props.executedAmount.value.toString(), currency: this.props.executedAmount.currency },
        budgetAmount: { value: this.props.amount.value.toString(), currency: this.props.amount.currency },
        excessAmount: { value: this.props.executedAmount.subtract(this.props.amount).value.toString(), currency: this.props.amount.currency }
      }));
    }
  }

  public expire(): void {
    if (this.props.status !== BudgetStatus.ACTIVE) {
      throw new BudgetNotActiveException();
    }
    this.props.status = BudgetStatus.EXPIRED;
    this.props.updatedAt = new Date();
    this.addDomainEvent(new BudgetExpiredEvent({
      aggregateId: this.id,
      userId: this.userId,
      categoryId: this.categoryId,
    }));
  }

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  public deactivate(_reason: 'CATEGORY_DELETED' | 'USER_REQUEST'): void {
    if (this.props.status !== BudgetStatus.ACTIVE) {
      throw new BudgetNotActiveException();
    }
    this.props.status = BudgetStatus.INACTIVE;
    this.props.updatedAt = new Date();
  }

  public reactivate(): void {
    if (this.props.status !== BudgetStatus.INACTIVE) {
      // Re-use BudgetNotActiveException or maybe create a BudgetAlreadyActiveException?
      // Actually, if it's expired, we shouldn't reactivate it. If it's active, it's a no-op or throw.
      // We will throw if it's not INACTIVE.
      if (this.props.status === BudgetStatus.ACTIVE) {
        return; // Idempotent
      }
      throw new Error('Only inactive budgets can be reactivated');
    }
    this.props.status = BudgetStatus.ACTIVE;
    this.props.updatedAt = new Date();
  }

  public executionPercentage(): number {
    return this.props.executedAmount.value.div(this.props.amount.value).mul(100).toNumber();
  }

  public remainingAmount(): Money {
    return this.props.amount.subtract(this.props.executedAmount);
  }

  public availableAmount(): Money {
    const remaining = this.remainingAmount();
    return remaining.value.lt(0) ? Money.zero(this.props.amount.currency) : remaining;
  }

  public isOverBudget(): boolean {
    return this.props.executedAmount.value.gt(this.props.amount.value);
  }

  public isActive(): boolean {
    return this.props.status === BudgetStatus.ACTIVE;
  }

  public containsDate(date: Date): boolean {
    const d = new Date(date).setHours(0, 0, 0, 0);
    const start = new Date(this.props.startDate).setHours(0, 0, 0, 0);
    const end = new Date(this.props.endDate).setHours(0, 0, 0, 0);
    return d >= start && d <= end;
  }

  public belongsToUser(userId: string): boolean {
    return this.props.userId === userId;
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../../prisma/prisma.service';
import { Money } from '@mymoney/shared';
import { Budget, BudgetPeriod, BudgetStatus } from '../domain/budget.entity';
import { IBudgetRepository } from '../domain/budget.repository.interface';

@Injectable()
export class PrismaBudgetRepository implements IBudgetRepository {
  constructor(private readonly prisma: PrismaService) {}

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async softDelete(_id: string, _userId: string, _deletedBy: string): Promise<void> {
    throw new Error('Method not implemented.');
  }

  async save(budget: Budget): Promise<void> {
    await this.prisma.budget.upsert({
      where: { id: budget.id },
      update: {
        amount: budget.amount.value.toNumber(),
        currency: budget.amount.currency,
        alert_threshold: budget.alertThreshold,
        executed_amount: budget.executedAmount.value.toNumber(),
        status: budget.status,
        updated_at: budget.updatedAt,
      },
      create: {
        id: budget.id,
        user_id: budget.userId,
        category_id: budget.categoryId,
        period: budget.period,
        amount: budget.amount.value.toNumber(),
        currency: budget.amount.currency,
        alert_threshold: budget.alertThreshold,
        executed_amount: budget.executedAmount.value.toNumber(),
        status: budget.status,
        start_date: budget.startDate,
        end_date: budget.endDate,
        created_at: budget.createdAt,
        updated_at: budget.updatedAt,
      },
    });
  }

  async findById(id: string, userId: string): Promise<Budget | null> {
    const data = await this.prisma.budget.findFirst({
      where: { id, user_id: userId },
    });
    if (!data) return null;
    return this.toDomain(data);
  }

  async exists(id: string): Promise<boolean> {
    const count = await this.prisma.budget.count({ where: { id } });
    return count > 0;
  }

  async findAllByUser(userId: string): Promise<Budget[]> {
    const data = await this.prisma.budget.findMany({
      where: { user_id: userId },
      orderBy: { start_date: 'desc' },
    });
    return data.map(this.toDomain);
  }

  async findActiveByUser(userId: string): Promise<Budget[]> {
    const data = await this.prisma.budget.findMany({
      where: { user_id: userId, status: 'ACTIVE' },
      orderBy: { start_date: 'desc' },
    });
    return data.map(this.toDomain);
  }

  async findByCategory(categoryId: string, userId: string): Promise<Budget[]> {
    const data = await this.prisma.budget.findMany({
      where: { category_id: categoryId, user_id: userId },
      orderBy: { start_date: 'desc' },
    });
    return data.map(this.toDomain);
  }

  async findActiveByCategoryAndDate(categoryId: string, userId: string, date: Date): Promise<Budget | null> {
    // Ensuring the date has time stripped for accurate range check in prisma if they are stored as Dates
    const d = new Date(date);
    d.setHours(0, 0, 0, 0);

    const data = await this.prisma.budget.findFirst({
      where: {
        category_id: categoryId,
        user_id: userId,
        status: 'ACTIVE',
        start_date: { lte: d },
        end_date: { gte: d },
      },
    });
    if (!data) return null;
    return this.toDomain(data);
  }

  async existsActiveBudget(userId: string, categoryId: string, period: BudgetPeriod, startDate: Date): Promise<boolean> {
    const d = new Date(startDate);
    d.setHours(0, 0, 0, 0);

    const count = await this.prisma.budget.count({
      where: {
        user_id: userId,
        category_id: categoryId,
        period,
        start_date: d,
        status: 'ACTIVE',
      },
    });
    return count > 0;
  }

  private toDomain(data: any): Budget {
    return Budget.reconstitute({
      id: data.id,
      userId: data.user_id,
      categoryId: data.category_id,
      period: data.period as BudgetPeriod,
      amount: Money.of(data.amount.toString(), data.currency),
      startDate: data.start_date,
      endDate: data.end_date,
      alertThreshold: data.alert_threshold,
      executedAmount: Money.of(data.executed_amount.toString(), data.currency),
      status: data.status as BudgetStatus,
      createdAt: data.created_at,
      updatedAt: data.updated_at,
    });
  }
}

