import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Money, IUnitOfWork, UNIT_OF_WORK } from '@mymoney/shared';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { Transaction } from '../../domain/transaction.entity';
import { CreateTransactionDto } from '../../presentation/dtos/create-transaction.dto';
import { TransactionDto } from '../../presentation/dtos/transaction.dto';
import { IAccountRepository, ACCOUNT_REPOSITORY } from '../../../accounts/domain/interfaces/account.repository.interface';
import { ICategoryRepository, CATEGORY_REPOSITORY } from '../../../categories/domain/category.repository.interface';
import { IncompatibleCategoryException } from '../../domain/exceptions/transaction.exceptions';
import { BalanceDelta } from '@mymoney/shared';


@Injectable()
export class CreateTransactionUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
    @Inject(ACCOUNT_REPOSITORY)
    private readonly accountRepository: IAccountRepository,
    @Inject(CATEGORY_REPOSITORY)
    private readonly categoryRepository: ICategoryRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, dto: CreateTransactionDto): Promise<TransactionDto> {
    const account = await this.accountRepository.findById(dto.account_id, userId);
    if (!account) {
      throw new NotFoundException('Account not found');
    }

    if (dto.category_id) {
      const category = await this.categoryRepository.findById(dto.category_id, userId);
      if (!category) {
        throw new NotFoundException('Category not found');
      }

      // Validate category compatibility
      if (!category.isCompatibleWith(dto.type)) {
        throw new IncompatibleCategoryException(dto.type, category.type);
      }
    }

    const amount = Money.of(dto.amount, account.currency);
    const date = new Date(dto.date);

    const transaction = Transaction.create({
      userId,
      accountId: dto.account_id,
      categoryId: dto.category_id ?? null,
      type: dto.type,
      amount,
      description: dto.description ?? null,
      date,
      transferPairId: null,
      isRecurring: false, // Default for MVP
    });

    // Update account balance synchronously within the use case to ensure it participates in UoW
    const delta = dto.type === 'INCOME' 
      ? BalanceDelta.increase(amount) 
      : BalanceDelta.decrease(amount);

    const balanceChangeEvent = account.applyBalanceDelta(delta, 'TRANSACTION_CREATED');

    await this.unitOfWork.execute(async () => {
      await this.transactionRepository.save(transaction);
      await this.accountRepository.save(account);
    });

    // Emit events
    transaction.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    this.eventEmitter.emit(balanceChangeEvent.type, balanceChangeEvent);
    transaction.clearDomainEvents();

    return TransactionDto.fromDomain(transaction);
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { randomUUID } from 'crypto';
import { Money, IUnitOfWork, UNIT_OF_WORK, BalanceDelta } from '@mymoney/shared';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { Transaction } from '../../domain/transaction.entity';
import { TransactionType } from '../../domain/transaction-type.enum';
import { CreateTransferDto } from '../../presentation/dtos/create-transaction.dto';
import { TransferPairDto, TransactionDto } from '../../presentation/dtos/transaction.dto';
import { IAccountRepository, ACCOUNT_REPOSITORY } from '../../../accounts/domain/interfaces/account.repository.interface';
import { TransferRequiresDifferentAccountsException } from '../../domain/exceptions/transaction.exceptions';


@Injectable()
export class CreateTransferUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
    @Inject(ACCOUNT_REPOSITORY)
    private readonly accountRepository: IAccountRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(userId: string, dto: CreateTransferDto): Promise<TransferPairDto> {
    if (dto.source_account_id === dto.destination_account_id) {
      throw new TransferRequiresDifferentAccountsException();
    }

    const sourceAccount = await this.accountRepository.findById(dto.source_account_id, userId);
    if (!sourceAccount) {
      throw new NotFoundException('Source account not found');
    }

    const destinationAccount = await this.accountRepository.findById(dto.destination_account_id, userId);
    if (!destinationAccount) {
      throw new NotFoundException('Destination account not found');
    }

    const sourceAmount = Money.of(dto.amount, sourceAccount.currency);
    const destinationAmount = Money.of(dto.destination_amount, destinationAccount.currency);
    const date = new Date(dto.date);
    const transferPairId = randomUUID();

    const sourceTransaction = Transaction.create({
      userId,
      accountId: dto.source_account_id,
      categoryId: null, // Transfers don't have categories by default
      type: TransactionType.EXPENSE,
      amount: sourceAmount,
      description: dto.description ?? 'Transferencia saliente',
      date,
      transferPairId,
      isRecurring: false,
    });

    const destinationTransaction = Transaction.create({
      userId,
      accountId: dto.destination_account_id,
      categoryId: null,
      type: TransactionType.INCOME,
      amount: destinationAmount,
      description: dto.description ?? 'Transferencia entrante',
      date,
      transferPairId,
      isRecurring: false,
    });

    // Update balances
    const sourceDelta = BalanceDelta.decrease(sourceAmount);
    const sourceBalanceEvent = sourceAccount.applyBalanceDelta(sourceDelta, 'TRANSACTION_CREATED');

    const destinationDelta = BalanceDelta.increase(destinationAmount);
    const destinationBalanceEvent = destinationAccount.applyBalanceDelta(destinationDelta, 'TRANSACTION_CREATED');

    // Save everything atomically
    await this.unitOfWork.execute(async () => {
      await this.transactionRepository.save(sourceTransaction);
      await this.transactionRepository.save(destinationTransaction);
      await this.accountRepository.save(sourceAccount);
      await this.accountRepository.save(destinationAccount);
    });

    // Emit all events
    sourceTransaction.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    destinationTransaction.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    this.eventEmitter.emit(sourceBalanceEvent.type, sourceBalanceEvent);
    this.eventEmitter.emit(destinationBalanceEvent.type, destinationBalanceEvent);

    sourceTransaction.clearDomainEvents();
    destinationTransaction.clearDomainEvents();

    return {
      transfer_pair_id: transferPairId,
      source_transaction: TransactionDto.fromDomain(sourceTransaction),
      destination_transaction: TransactionDto.fromDomain(destinationTransaction),
    };
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { IUnitOfWork, UNIT_OF_WORK, BalanceDelta } from '@mymoney/shared';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { IAccountRepository, ACCOUNT_REPOSITORY } from '../../../accounts/domain/interfaces/account.repository.interface';


@Injectable()
export class DeleteTransactionUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
    @Inject(ACCOUNT_REPOSITORY)
    private readonly accountRepository: IAccountRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(id: string, userId: string): Promise<void> {
    const transaction = await this.transactionRepository.findById(id, userId);
    if (!transaction) {
      throw new NotFoundException('Transaction not found');
    }

    if (transaction.isDeleted) {
      return;
    }

    const account = await this.accountRepository.findById(transaction.accountId, userId);
    if (!account) {
      throw new NotFoundException('Account not found');
    }

    // Soft delete transaction
    transaction.softDelete(userId);

    // Revert balance effect
    let delta: BalanceDelta;
    if (transaction.type === 'INCOME') {
      delta = BalanceDelta.decrease(transaction.amount);
    } else if (transaction.type === 'EXPENSE') {
      delta = BalanceDelta.increase(transaction.amount);
    } else {
      // Transfer shouldn't reach here (validated in entity softDelete method)
      delta = BalanceDelta.increase(transaction.amount); // fallback to satisfy TS, though it throws before
    }

    const balanceChangeEvent = account.applyBalanceDelta(delta, 'TRANSACTION_DELETED');

    await this.unitOfWork.execute(async () => {
      await this.transactionRepository.save(transaction);
      await this.accountRepository.save(account);
    });

    transaction.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    this.eventEmitter.emit(balanceChangeEvent.type, balanceChangeEvent);
    transaction.clearDomainEvents();
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { IUnitOfWork, UNIT_OF_WORK, BalanceDelta } from '@mymoney/shared';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { IAccountRepository, ACCOUNT_REPOSITORY } from '../../../accounts/domain/interfaces/account.repository.interface';
import { Account } from '../../../accounts/domain/account.entity';


@Injectable()
export class DeleteTransferUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
    @Inject(ACCOUNT_REPOSITORY)
    private readonly accountRepository: IAccountRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(pairId: string, userId: string): Promise<void> {
    const transactions = await this.transactionRepository.findByTransferPairId(pairId, userId);

    if (transactions.length === 0) {
      throw new NotFoundException('Transfer pair not found');
    }

    // Filter out already deleted transactions
    const activeTransactions = transactions.filter(t => !t.isDeleted);
    if (activeTransactions.length === 0) {
      return;
    }

    // Load unique accounts
    const accountIds = [...new Set(activeTransactions.map(t => t.accountId))];
    const accountsMap = new Map<string, Account>();

    for (const accId of accountIds) {
      const account = await this.accountRepository.findById(accId, userId);
      if (!account) {
        throw new NotFoundException(`Account ${accId} not found`);
      }
      accountsMap.set(accId, account);
    }

    const balanceEvents = [];

    for (const transaction of activeTransactions) {
      const account = accountsMap.get(transaction.accountId)!;

      transaction.softDeleteAsTransfer(userId);

      let delta: BalanceDelta;
      if (transaction.type === 'INCOME') {
        delta = BalanceDelta.decrease(transaction.amount);
      } else {
        delta = BalanceDelta.increase(transaction.amount);
      }

      const balanceChangeEvent = account.applyBalanceDelta(delta, 'TRANSACTION_DELETED');
      balanceEvents.push(balanceChangeEvent);
    }

    await this.unitOfWork.execute(async () => {
      for (const t of activeTransactions) {
        await this.transactionRepository.save(t);
      }
      for (const acc of Array.from(accountsMap.values())) {
        await this.accountRepository.save(acc);
      }
    });

    for (const t of activeTransactions) {
      t.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
      t.clearDomainEvents();
    }
    balanceEvents.forEach((event: any) => this.eventEmitter.emit(event.type, event));
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { TransactionPaginatedResponseDto, TransactionDto } from '../../presentation/dtos/transaction.dto';

@Injectable()
export class ListTransactionsUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository
  ) {}

  async execute(userId: string, filters: any, page: number, limit: number): Promise<TransactionPaginatedResponseDto> {
    const skip = (page - 1) * limit;
    const [transactions, total] = await this.transactionRepository.findMany(userId, filters, skip, limit);

    const totalPages = Math.ceil(total / limit);

    return {
      data: transactions.map(t => TransactionDto.fromDomain(t)),
      meta: {
        total_items: total,
        total_pages: totalPages,
        current_page: page,
        per_page: limit,
        has_next: page < totalPages,
        has_previous: page > 1,
      },
    };
  }
}

import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Money, IUnitOfWork, UNIT_OF_WORK, BalanceDelta } from '@mymoney/shared';
import { ITransactionRepository, TRANSACTION_REPOSITORY } from '../../domain/transaction.repository.interface';
import { UpdateTransactionDto } from '../../presentation/dtos/create-transaction.dto';
import { TransactionDto } from '../../presentation/dtos/transaction.dto';
import { IAccountRepository, ACCOUNT_REPOSITORY } from '../../../accounts/domain/interfaces/account.repository.interface';
import { ICategoryRepository, CATEGORY_REPOSITORY } from '../../../categories/domain/category.repository.interface';

import { IncompatibleCategoryException, CannotEditTransactionTypeException } from '../../domain/exceptions/transaction.exceptions';

@Injectable()
export class UpdateTransactionUseCase {
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
    @Inject(ACCOUNT_REPOSITORY)
    private readonly accountRepository: IAccountRepository,
    @Inject(CATEGORY_REPOSITORY)
    private readonly categoryRepository: ICategoryRepository,
    @Inject(UNIT_OF_WORK)
    private readonly unitOfWork: IUnitOfWork,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(id: string, userId: string, dto: UpdateTransactionDto): Promise<TransactionDto> {
    const transaction = await this.transactionRepository.findById(id, userId);
    if (!transaction) {
      throw new NotFoundException('Transaction not found');
    }

    // Load account only if amount changes
    let account = null;
    let balanceChangeEvent = null;

    if (dto.amount) {
      account = await this.accountRepository.findById(transaction.accountId, userId);
      if (!account) throw new NotFoundException('Account not found');

      const newAmount = Money.of(dto.amount, account.currency);
      const previousAmount = transaction.amount;

      if (!newAmount.value.eq(previousAmount.value)) {
        // Delta = New - Old. 
        // But wait! If it's an EXPENSE, an increase in amount means we subtract MORE from the account.
        // If it's an INCOME, an increase in amount means we add MORE to the account.

        let delta: BalanceDelta;

        if (transaction.type === 'INCOME') {
          // If previous was 100, new is 150. Delta = +50.
          // If previous was 150, new is 100. Delta = -50.
          const diff = newAmount.subtract(previousAmount);
          delta = diff.value.gte(0) ? BalanceDelta.increase(diff) : BalanceDelta.decrease(Money.of(diff.value.abs(), diff.currency));
        } else if (transaction.type === 'EXPENSE') {
          // If previous was 100 (account -100), new is 150 (account -150). We need to subtract 50.
          // If previous was 150 (account -150), new is 100 (account -100). We need to add 50.
          const diff = newAmount.subtract(previousAmount);
          delta = diff.value.gte(0) ? BalanceDelta.decrease(diff) : BalanceDelta.increase(Money.of(diff.value.abs(), diff.currency));
        } else {
          // It's a transfer, which cannot be edited individually. But transaction.updateAmount validates that.
          throw new CannotEditTransactionTypeException(); 
        }

        balanceChangeEvent = account.applyBalanceDelta(delta, 'TRANSACTION_UPDATED');
        transaction.updateAmount(newAmount, userId);
      }
    }

    if (dto.date) {
      transaction.updateDate(new Date(dto.date), userId);
    }

    if (dto.category_id !== undefined) {
      if (dto.category_id !== null) {
        const category = await this.categoryRepository.findById(dto.category_id, userId);
        if (!category) throw new NotFoundException('Category not found');
        if (!category.isCompatibleWith(transaction.type)) {
          throw new IncompatibleCategoryException(transaction.type, category.type);
        }
      }
      transaction.updateCategory(dto.category_id, userId);
    }

    if (dto.description !== undefined) {
      transaction.updateDescription(dto.description, userId);
    }

    await this.unitOfWork.execute(async () => {
      await this.transactionRepository.save(transaction);
      if (account) {
        await this.accountRepository.save(account);
      }
    });

    transaction.getDomainEvents().forEach((event: any) => this.eventEmitter.emit(event.type, event));
    if (balanceChangeEvent) {
      this.eventEmitter.emit(balanceChangeEvent.type, balanceChangeEvent);
    }
    transaction.clearDomainEvents();

    return TransactionDto.fromDomain(transaction);
  }
}

import { randomUUID } from 'crypto';
import { Money, TransactionCreatedEvent, TransactionDeletedEvent, TransactionAmountChangedEvent, TransactionDateChangedEvent, TransactionCategoryChangedEvent } from '@mymoney/shared';
import { TransactionType } from './transaction-type.enum';
import { 
  InvalidTransactionAmountException, 
  InvalidTransactionDateException, 
  CannotEditTransferTransactionException
} from './exceptions/transaction.exceptions';

export interface TransactionProps {
  id: string;
  userId: string;
  accountId: string;
  categoryId: string | null;
  type: TransactionType;
  amount: Money;
  description: string | null;
  date: Date;
  transferPairId: string | null;
  isRecurring: boolean;
  createdAt: Date;
  createdBy: string | null;
  updatedAt: Date;
  updatedBy: string | null;
  deletedAt: Date | null;
  deletedBy: string | null;
}

export class Transaction {
  private props: TransactionProps;
  private domainEvents: unknown[] = [];

  private constructor(props: TransactionProps) {
    this.props = props;
  }

  // Getters
  get id(): string { return this.props.id; }
  get userId(): string { return this.props.userId; }
  get accountId(): string { return this.props.accountId; }
  get categoryId(): string | null { return this.props.categoryId; }
  get type(): TransactionType { return this.props.type; }
  get amount(): Money { return this.props.amount; }
  get description(): string | null { return this.props.description; }
  get date(): Date { return this.props.date; }
  get transferPairId(): string | null { return this.props.transferPairId; }
  get isRecurring(): boolean { return this.props.isRecurring; }
  get createdAt(): Date { return this.props.createdAt; }
  get createdBy(): string | null { return this.props.createdBy; }
  get updatedAt(): Date { return this.props.updatedAt; }
  get updatedBy(): string | null { return this.props.updatedBy; }
  get deletedAt(): Date | null { return this.props.deletedAt; }
  get deletedBy(): string | null { return this.props.deletedBy; }

  get isDeleted(): boolean {
    return this.props.deletedAt !== null;
  }

  get isTransfer(): boolean {
    return this.props.transferPairId !== null;
  }

  // Events
  public getDomainEvents(): unknown[] {
    return [...this.domainEvents];
  }

  public clearDomainEvents(): void {
    this.domainEvents = [];
  }

  private addDomainEvent(event: any): void {
    this.domainEvents.push(event);
  }

  /**
   * Validates invariants before creation or update
   */
  private static validateDate(date: Date): void {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const maxFutureDate = new Date(today);
    maxFutureDate.setDate(maxFutureDate.getDate() + 7);

    if (date > maxFutureDate) {
      throw new InvalidTransactionDateException();
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  private validateNotTransfer(_operation: string): void {
    if (this.isTransfer) {
      throw new CannotEditTransferTransactionException();
    }
  }

  /**
   * Factory method for creating a new Transaction
   */
  public static create(
    props: Omit<TransactionProps, 'id' | 'createdAt' | 'createdBy' | 'updatedAt' | 'updatedBy' | 'deletedAt' | 'deletedBy'>
  ): Transaction {
    if (props.amount.value.lte(0)) {
      throw new InvalidTransactionAmountException();
    }

    Transaction.validateDate(props.date);

    const transaction = new Transaction({
      ...props,
      id: randomUUID(),
      createdAt: new Date(),
      createdBy: props.userId,
      updatedAt: new Date(),
      updatedBy: props.userId,
      deletedAt: null,
      deletedBy: null,
    });

    transaction.addDomainEvent(new TransactionCreatedEvent({
      transactionId: transaction.id,
      userId: transaction.userId,
      accountId: transaction.accountId,
      categoryId: transaction.categoryId,
      amount: { value: transaction.amount.value.toString(), currency: transaction.amount.currency },
      transactionType: transaction.type,
      date: transaction.date.toISOString(),
      transferPairId: transaction.transferPairId,
      occurredAt: new Date(),
    }));

    return transaction;
  }

  /**
   * Reconstitutes an existing Transaction from DB
   */
  public static reconstitute(props: TransactionProps): Transaction {
    return new Transaction(props);
  }

  /**
   * Modifies the amount (TRX-R06)
   */
  public updateAmount(newAmount: Money, updatedBy: string): void {
    this.validateNotTransfer('updateAmount');

    if (newAmount.value.lte(0)) {
      throw new InvalidTransactionAmountException();
    }

    if (this.props.amount.currency !== newAmount.currency) {
      throw new Error('Cannot change transaction currency'); // Internal error, shouldn't happen from API
    }

    if (this.props.amount.value.eq(newAmount.value)) {
      return;
    }

    const previousAmount = this.props.amount;
    const delta = newAmount.subtract(previousAmount);

    this.props.amount = newAmount;
    this.props.updatedAt = new Date();
    this.props.updatedBy = updatedBy;

    this.addDomainEvent(new TransactionAmountChangedEvent({
      transactionId: this.id,
      userId: this.userId,
      accountId: this.accountId,
      categoryId: this.categoryId,
      previousAmount: { value: previousAmount.value.toString(), currency: previousAmount.currency },
      newAmount: { value: newAmount.value.toString(), currency: newAmount.currency },
      delta: { value: delta.value.toString(), currency: delta.currency },
      transactionType: this.type,
      date: this.date.toISOString(),
      occurredAt: new Date(),
    }));
  }

  /**
   * Modifies the date (TRX-R07)
   */
  public updateDate(newDate: Date, updatedBy: string): void {
    this.validateNotTransfer('updateDate');

    // Convert both dates to ISO date strings for comparison to avoid time discrepancies
    const currentDateStr = this.props.date.toISOString().split('T')[0];
    const newDateStr = newDate.toISOString().split('T')[0];

    if (currentDateStr === newDateStr) {
      return;
    }

    Transaction.validateDate(newDate);

    const previousDate = this.props.date;
    this.props.date = newDate;
    this.props.updatedAt = new Date();
    this.props.updatedBy = updatedBy;

    this.addDomainEvent(new TransactionDateChangedEvent({
      transactionId: this.id,
      userId: this.userId,
      categoryId: this.categoryId,
      amount: { value: this.amount.value.toString(), currency: this.amount.currency },
      transactionType: this.type,
      previousDate: previousDate.toISOString(),
      newDate: newDate.toISOString(),
      occurredAt: new Date(),
    }));
  }

  /**
   * Modifies the category (TRX-R08)
   */
  public updateCategory(newCategoryId: string | null, updatedBy: string): void {
    this.validateNotTransfer('updateCategory');

    if (this.props.categoryId === newCategoryId) {
      return;
    }

    const previousCategoryId = this.props.categoryId;
    this.props.categoryId = newCategoryId;
    this.props.updatedAt = new Date();
    this.props.updatedBy = updatedBy;

    this.addDomainEvent(new TransactionCategoryChangedEvent({
      transactionId: this.id,
      userId: this.userId,
      amount: { value: this.amount.value.toString(), currency: this.amount.currency },
      transactionType: this.type,
      date: this.date.toISOString(),
      previousCategoryId,
      newCategoryId,
      occurredAt: new Date(),
    }));
  }

  /**
   * Modifies the description
   */
  public updateDescription(newDescription: string | null, updatedBy: string): void {
    this.validateNotTransfer('updateDescription');

    if (this.props.description === newDescription) return;

    this.props.description = newDescription;
    this.props.updatedAt = new Date();
    this.props.updatedBy = updatedBy;
  }

  /**
   * Archiva la transacción (Soft Delete, TRX-R09, TRX-R10)
   */
  public softDelete(deletedBy: string): void {
    if (this.isDeleted) return;

    // Soft delete of transfer individual items is NOT allowed (TRF-R05). 
    // They must be deleted by deleting the transfer pair.
    if (this.isTransfer) {
      throw new CannotEditTransferTransactionException();
    }

    this.props.deletedAt = new Date();
    this.props.deletedBy = deletedBy;
    this.props.updatedAt = new Date();
    this.props.updatedBy = deletedBy;

    this.addDomainEvent(new TransactionDeletedEvent({
      transactionId: this.id,
      userId: this.userId,
      accountId: this.accountId,
      categoryId: this.categoryId,
      amount: { value: this.amount.value.toString(), currency: this.amount.currency },
      transactionType: this.type,
      date: this.date.toISOString(),
      deletedBy,
      occurredAt: new Date(),
    }));
  }

  /**
   * Soft Delete bypassing transfer check (for internal use when deleting a transfer pair)
   */
  public softDeleteAsTransfer(deletedBy: string): void {
    if (this.isDeleted) return;
    if (!this.isTransfer) throw new Error('Not a transfer');

    this.props.deletedAt = new Date();
    this.props.deletedBy = deletedBy;
    this.props.updatedAt = new Date();
    this.props.updatedBy = deletedBy;

    this.addDomainEvent(new TransactionDeletedEvent({
      transactionId: this.id,
      userId: this.userId,
      accountId: this.accountId,
      categoryId: this.categoryId,
      amount: { value: this.amount.value.toString(), currency: this.amount.currency },
      transactionType: this.type,
      date: this.date.toISOString(),
      deletedBy,
      occurredAt: new Date(),
    }));
  }
}

import { IRepository } from '@mymoney/shared';
import { Transaction } from './transaction.entity';

export const TRANSACTION_REPOSITORY = Symbol('TRANSACTION_REPOSITORY');

export interface ITransactionRepository extends IRepository<Transaction, string> {
  findByTransferPairId(transferPairId: string, userId: string): Promise<Transaction[]>;
  findMany(userId: string, filters: any, skip: number, take: number): Promise<[Transaction[], number]>;
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../../../prisma/prisma.service';
import { ITransactionRepository } from '../../domain/transaction.repository.interface';
import { Transaction } from '../../domain/transaction.entity';
import { TransactionType } from '../../domain/transaction-type.enum';
import { Money } from '@mymoney/shared';
import { prismaTransactionStorage } from '../../../../prisma/prisma-unit-of-work';
import { Prisma } from '@mymoney/db';

@Injectable()
export class PrismaTransactionRepository implements ITransactionRepository {
  constructor(private readonly defaultPrisma: PrismaService) {}

  private get prisma(): Prisma.TransactionClient {
    return prismaTransactionStorage.getStore() ?? this.defaultPrisma;
  }

  private toDomain(raw: any): Transaction {
    return Transaction.reconstitute({
      id: raw.id,
      userId: raw.user_id,
      accountId: raw.account_id,
      categoryId: raw.category_id,
      type: raw.type as TransactionType,
      amount: Money.of(raw.amount, raw.currency),
      description: raw.description,
      date: new Date(raw.date),
      transferPairId: raw.transfer_pair_id,
      isRecurring: raw.is_recurring,
      createdAt: raw.created_at,
      createdBy: raw.created_by,
      updatedAt: raw.updated_at,
      updatedBy: raw.updated_by,
      deletedAt: raw.deleted_at,
      deletedBy: raw.deleted_by,
    });
  }

  private toPersistence(entity: Transaction): any {
    return {
      id: entity.id,
      user_id: entity.userId,
      account_id: entity.accountId,
      category_id: entity.categoryId,
      type: entity.type,
      amount: entity.amount.value.toString(),
      currency: entity.amount.currency,
      description: entity.description,
      date: entity.date,
      transfer_pair_id: entity.transferPairId,
      is_recurring: entity.isRecurring,
      created_at: entity.createdAt,
      created_by: entity.createdBy,
      updated_at: entity.updatedAt,
      updated_by: entity.updatedBy,
      deleted_at: entity.deletedAt,
      deleted_by: entity.deletedBy,
    };
  }

  async findById(id: string, userId: string): Promise<Transaction | null> {
    const raw = await this.prisma.transaction.findFirst({
      where: {
        id,
        user_id: userId,
        deleted_at: null,
      },
    });
    if (!raw) return null;
    return this.toDomain(raw);
  }

  async save(entity: Transaction): Promise<void> {
    const data = this.toPersistence(entity);
    await this.prisma.transaction.upsert({
      where: { id: entity.id },
      create: data,
      update: data,
    });
  }

  async exists(id: string, userId: string): Promise<boolean> {
    const count = await this.prisma.transaction.count({
      where: {
        id,
        user_id: userId,
        deleted_at: null,
      },
    });
    return count > 0;
  }

  async softDelete(id: string, userId: string, deletedBy: string): Promise<void> {
    await this.prisma.transaction.updateMany({
      where: {
        id,
        user_id: userId,
      },
      data: {
        deleted_at: new Date(),
        deleted_by: deletedBy,
        updated_at: new Date(),
        updated_by: deletedBy,
      },
    });
  }

  async findByTransferPairId(transferPairId: string, userId: string): Promise<Transaction[]> {
    const raw = await this.prisma.transaction.findMany({
      where: {
        transfer_pair_id: transferPairId,
        user_id: userId,
      },
    });
    return raw.map(r => this.toDomain(r));
  }

  async findMany(userId: string, filters: any, skip: number, take: number): Promise<[Transaction[], number]> {
    const where: any = {
      user_id: userId,
      deleted_at: null,
    };

    if (filters.account_id) where.account_id = filters.account_id;
    if (filters.category_id) where.category_id = filters.category_id;
    if (filters.type) where.type = filters.type;

    // date ranges
    if (filters.start_date || filters.end_date) {
      where.date = {};
      if (filters.start_date) where.date.gte = new Date(filters.start_date);
      if (filters.end_date) where.date.lte = new Date(filters.end_date);
    }

    const [raw, count] = await Promise.all([
      this.prisma.transaction.findMany({
        where,
        skip,
        take,
        orderBy: { date: 'desc' },
      }),
      this.prisma.transaction.count({ where }),
    ]);

    return [raw.map(r => this.toDomain(r)), count];
  }
}

import { Controller, Get, Post, Patch, Delete, Body, Param, Query, UseGuards, Request, ParseIntPipe, DefaultValuePipe, HttpCode, HttpStatus } from '@nestjs/common';
import { CreateTransactionDto, UpdateTransactionDto } from '../presentation/dtos/create-transaction.dto';
import { TransactionDto, TransactionPaginatedResponseDto } from '../presentation/dtos/transaction.dto';
import { CreateTransactionUseCase } from '../application/use-cases/create-transaction.use-case';
import { UpdateTransactionUseCase } from '../application/use-cases/update-transaction.use-case';
import { DeleteTransactionUseCase } from '../application/use-cases/delete-transaction.use-case';
import { ListTransactionsUseCase } from '../application/use-cases/list-transactions.use-case';
import { SessionGuard } from '../../../auth/session.guard';

@UseGuards(SessionGuard)
@Controller({ path: 'transactions', version: '1' })
export class TransactionsController {
  constructor(
    private readonly createTransactionUseCase: CreateTransactionUseCase,
    private readonly updateTransactionUseCase: UpdateTransactionUseCase,
    private readonly deleteTransactionUseCase: DeleteTransactionUseCase,
    private readonly listTransactionsUseCase: ListTransactionsUseCase
  ) {}

  @Get()
  async findAll(
    @Request() req: any,
    @Query('page', new DefaultValuePipe(1), ParseIntPipe) page: number,
    @Query('limit', new DefaultValuePipe(10), ParseIntPipe) limit: number,
    @Query('account_id') accountId?: string,
    @Query('category_id') categoryId?: string,
    @Query('type') type?: string,
    @Query('start_date') startDate?: string,
    @Query('end_date') endDate?: string
  ): Promise<TransactionPaginatedResponseDto> {
    const userId = req.user.id;
    const filters = {
      account_id: accountId,
      category_id: categoryId,
      type,
      start_date: startDate,
      end_date: endDate,
    };
    return this.listTransactionsUseCase.execute(userId, filters, page, limit);
  }

  @Post()
  async create(
    @Request() req: any,
    @Body() dto: CreateTransactionDto
  ): Promise<{ data: TransactionDto }> {
    const userId = req.user.id;
    const data = await this.createTransactionUseCase.execute(userId, dto);
    return { data };
  }

  @Patch(':id')
  async update(
    @Request() req: any,
    @Param('id') id: string,
    @Body() dto: UpdateTransactionDto
  ): Promise<{ data: TransactionDto }> {
    const userId = req.user.id;
    const data = await this.updateTransactionUseCase.execute(id, userId, dto);
    return { data };
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  async remove(
    @Request() req: any,
    @Param('id') id: string
  ): Promise<void> {
    const userId = req.user.id;
    await this.deleteTransactionUseCase.execute(id, userId);
  }
}

import { Controller, Post, Delete, Body, Param, UseGuards, Request, HttpCode, HttpStatus } from '@nestjs/common';
import { CreateTransferDto } from '../presentation/dtos/create-transaction.dto';
import { TransferPairDto } from '../presentation/dtos/transaction.dto';
import { CreateTransferUseCase } from '../application/use-cases/create-transfer.use-case';
import { DeleteTransferUseCase } from '../application/use-cases/delete-transfer.use-case';
